public class ArchiveUtils_sanitize_TriageGen1Test {









    @Test
    public void testSanitize_NullBlock() {
        // Character.UnicodeBlock.of(c) returns null for some unassigned/invalid chars
        // We can use a surrogate pair or an unassigned character if the environment allows.
        // For testing purposes, we attempt to trigger the null block branch.
        // High surrogates often return null for UnicodeBlock.of()
        String input = "\uD83D"; 
        String expected = "?";
        assertEquals(expected, ArchiveUtils.sanitize(input));
    }




}

